package com.adaptivelearning.knowledgebase.application;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class KnowledgeUtilitiesTest {@Test void chunkerCreatesBoundedOverlappingChunks(){var c=new DocumentChunker().chunk("这是一个用于测试分块的段落。".repeat(100),120,180);assertThat(c).hasSizeGreaterThan(2);assertThat(c).allMatch(x->x.length()<=180);}@Test void relatedTextScoresAboveUnrelated(){TextVectorizer v=new TextVectorizer();double related=v.keyword("Spring Boot 自动配置","Spring Boot 通过自动配置简化应用开发");double unrelated=v.keyword("Spring Boot 自动配置","古典音乐和绘画艺术");assertThat(related).isGreaterThan(unrelated);}}
